// Arma el reporte de observabilidad a partir del Execution Log del agente
const agent = $input.first().json;
const trigger = $('Chat Trigger').first().json;
const steps = agent.intermediateSteps || [];

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const str = (v) => typeof v === 'string' ? v : JSON.stringify(v, null, 2);

const pasosHtml = steps.map((s, i) => `
  <h4>Paso ${i + 1}: herramienta "${esc(s.action?.tool)}"</h4>
  <p><b>Razonamiento / log:</b></p><pre>${esc(s.action?.log)}</pre>
  <p><b>Entrada:</b></p><pre>${esc(str(s.action?.toolInput))}</pre>
  <p><b>Resultado:</b></p><pre>${esc(str(s.observation))}</pre>`).join('<hr>');

const herramientaUsada = steps.length > 0;
const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });

const cuerpoHtml = `
  <h2>Reporte de observabilidad - Agente Aqua</h2>
  <p><b>Fecha:</b> ${fecha}<br>
  <b>Session_ID:</b> ${esc(trigger.sessionId)}<br>
  <b>Herramienta invocada:</b> ${herramientaUsada ? 'SÍ (' + steps.length + ' paso/s)' : 'NO'}</p>
  <h3>Mensaje del cliente</h3><pre>${esc(trigger.chatInput)}</pre>
  <h3>Respuesta del agente</h3><pre>${esc(agent.output)}</pre>
  <h3>Execution Log</h3>
  ${herramientaUsada ? pasosHtml : '<p>El agente respondió sin invocar herramientas.</p>'}`;

return [{
  json: {
    sessionId: trigger.sessionId,
    herramientaUsada,
    cantidadPasos: steps.length,
    asunto: `[Aqua] ${herramientaUsada ? 'Herramienta ejecutada' : 'Conversación'} - sesión ${String(trigger.sessionId).slice(0, 8)}`,
    cuerpoHtml
  }
}];
